const seniorTopics={"daily": ["ia-adrc", "ia-cil-a2i", "ia-cil-cicil", "ia-cil-drc-siouxland", "ia-cil-scicil", "ia-cil-swicil"], "accessibility": ["ia-adrc", "ia-cil-a2i", "ia-cil-cicil", "ia-cil-drc-siouxland", "ia-cil-scicil", "ia-cil-swicil"], "vision": ["ia-adrc"], "hearing": ["ia-adrc"], "memory": ["alz-dementia-support", "ia-adrc"], "costs": ["ia-ship", "ia-adrc", "ia-legal-programs"], "rights": ["ia-ombudsman", "ia-legal-programs"]};
const ohioLiving=DATA.filter(x=>x.resource_role==='independent_living').map(x=>x.program_id),ohioCaregivers=DATA.filter(x=>x.resource_role==='caregiver_support').map(x=>x.program_id);
const ohioCenters=DATA.filter(x=>x.resource_role==='senior_center').map(x=>x.program_id);
